		["rogue-subtlety"] = {
			{ level = 10, lines = {
				{ spellId = 14278, name = "Ghostly Strike", condition = "Ghostly Strike on cooldown at four combo points or fewer: it hits harder than Hemorrhage for 10 more energy (Hemorrhage costs 30 with Efficient Strikes) and gives a combo point." },
				{ spellId = 6760, name = "Eviscerate", condition = "Eviscerate at three or more combo points while Rupture is ticking, only before you have Death Mark: from 40, those points go into Death Mark instead." },
				{ spellId = 5171, name = "Slice and Dice", condition = "Slice and Dice at three or more combo points while Rupture is ticking, when it is down or has under 3 seconds left." },
				{ spellId = 53, name = "Backstab", condition = "Backstab from behind with a dagger in your main hand is the builder until Hemorrhage: it hits far harder than Sinister Strike, and every point of Opportunity, from 13, adds 4% to it." },
				{ spellId = 1757, name = "Sinister Strike", condition = "Sinister Strike before Hemorrhage only when Backstab cannot be cast: no dagger in the main hand, or the target is facing you." },
			} },
