				{ spellId = 1325756, name = "Death Mark", condition = "Death Mark at four or more combo points while Rupture is ticking, and between marks the points Rupture and Slice and Dice do not need wait for the next one: for 6 seconds it stores a share of everything you hit the target for, Rupture and Garrote at twice the rate, then deals it back at once." },
				{ spellId = 11299, name = "Eviscerate", condition = "Eviscerate at three or more combo points while Rupture is ticking, only before you have Death Mark: from 40, those points go into Death Mark instead." },
				{ spellId = 6774, name = "Slice and Dice", condition = "Slice and Dice at three or more combo points while Rupture is ticking, when it is down or has under 3 seconds left." },
				{ spellId = 16511, name = "Hemorrhage", condition = "Hemorrhage, your builder for every global nothing above takes, and it keeps Hemorrhage's debuff up: one combo point a cast, and the debuff makes your Rupture and Garrote hit 15% harder." },
				{ spellId = 11280, name = "Backstab", condition = "Backstab from behind with a dagger in your main hand is the builder until Hemorrhage: it hits far harder than Sinister Strike, and every point of Opportunity, from 13, adds 4% to it." },
				{ spellId = 11294, name = "Sinister Strike", condition = "Sinister Strike before Hemorrhage only when Backstab cannot be cast: no dagger in the main hand, or the target is facing you." },
